begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id) values(md5('sets_a')::uuid),(md5('sets_b')::uuid);
insert into public.profiles(id,display_name) values(md5('sets_a')::uuid,'Sets A'),(md5('sets_b')::uuid,'Sets B');
select ok(not has_function_privilege('anon','public.log_workout_set(uuid,uuid,text,integer,uuid,integer,numeric,text,text,boolean,integer,numeric,text,jsonb)','execute'),'anonymous set RPC denied');
select ok(not has_column_privilege('authenticated','public.workout_sets','revision','UPDATE'),'revision is server maintained');
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('sets_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.session',public.start_ad_hoc_workout()::text,true);
select set_config('body_test.item',public.edit_workout(current_setting('body_test.session')::uuid,'add',(select id from public.exercises where slug='barbell_bench_press'))::text,true);
-- Privileged fixture cleanup isolates legacy manual-row RPC tests; initialization is tested separately.
reset role;
delete from public.workout_sets where workout_exercise_id=current_setting('body_test.item')::uuid;
set local role authenticated;
select lives_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'add',null,md5('add1')::uuid)$$,'create a blank pending set');
select ok((select status='pending' and actual_reps is null and actual_weight_kg is null and completed_at is null from public.workout_sets where id=md5('set1')::uuid),'blank is not zero or complete');
select lives_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'add',null,md5('add1')::uuid)$$,'repeated add is idempotent');
select is((select count(*)::int from public.workout_sets where workout_exercise_id=current_setting('body_test.item')::uuid),1,'one stable set ID after retry');
select lives_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'save',0,md5('save1')::uuid,8,60,'warm_up','external',true)$$,'complete a warm-up with actual values');
select ok((select status='completed' and set_type='warm_up' and revision=1 and completed_at is not null from public.workout_sets where id=md5('set1')::uuid),'completion records type, actuals and timestamp');
select lives_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'save',0,md5('save1')::uuid,8,60,'warm_up','external',true)$$,'same mutation retries after response loss');
select is((select revision from public.workout_sets where id=md5('set1')::uuid),1,'retry did not apply twice');
select throws_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'save',0,md5('stale')::uuid,99,90)$$,'40001',null,'stale device cannot silently overwrite');
select is((select actual_reps from public.workout_sets where id=md5('set1')::uuid),8,'conflict preserves committed actuals');
select lives_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'save',1,md5('reopen')::uuid,7,62,'drop','external',false)$$,'reopen and edit actuals/type');
select ok((select status='pending' and completed_at is null and set_type='drop' and actual_reps=7 from public.workout_sets where id=md5('set1')::uuid),'unchecking explicitly clears completion');
select throws_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'save',2,md5('invalid')::uuid,null,null,'working','external',true)$$,'22023',null,'incomplete external performance cannot complete');
select throws_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'save',2,md5('invalid2')::uuid,-1,2)$$,'22023',null,'negative reps rejected');
select throws_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'save',2,md5('invalid3')::uuid,8,'NaN'::numeric)$$,'22023',null,'NaN load rejected');
select throws_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'save',2,md5('invalid4')::uuid,8,null,'working','bodyweight',true)$$,'22023',null,'loaded bench cannot be recorded as bodyweight');
select lives_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set2')::uuid,'add',null,md5('add2')::uuid,7,62,'rest_pause')$$,'new default values remain pending, including advanced type');
select lives_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set2')::uuid,'move',0,md5('move2')::uuid,null,null,'working','external',false,-1)$$,'swap ordered set identities atomically');
select is((select position from public.workout_sets where id=md5('set2')::uuid),1,'second set moved first');
select is((select position from public.workout_sets where id=md5('set1')::uuid),2,'first set moved second');
select lives_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set2')::uuid,'remove',1,md5('remove2')::uuid)$$,'soft delete an incorrect set');
select ok((select deleted_at is not null and set_type='rest_pause' and actual_reps=7 from public.workout_sets where id=md5('set2')::uuid),'deletion retains identity and recorded content');
select set_config('request.jwt.claims',json_build_object('sub',md5('sets_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from public.workout_sets where id=md5('set1')::uuid),0,'other user cannot read set');
select throws_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'save',3,md5('forged')::uuid,99,99)$$,'42501',null,'other user cannot edit set');
select set_config('request.jwt.claims',json_build_object('sub',md5('sets_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.bw',public.edit_workout(current_setting('body_test.session')::uuid,'add',(select id from public.exercises where slug='push_up'))::text,true);
reset role;
delete from public.workout_sets where workout_exercise_id=current_setting('body_test.bw')::uuid;
set local role authenticated;
select lives_ok($$select * from public.log_workout_set(current_setting('body_test.bw')::uuid,md5('bw')::uuid,'add',null,md5('bwadd')::uuid,10,null,'working','bodyweight')$$,'bodyweight pending set keeps load null');
select lives_ok($$select * from public.log_workout_set(current_setting('body_test.bw')::uuid,md5('bw')::uuid,'save',0,md5('bwcomplete')::uuid,10,null,'working','bodyweight',true)$$,'bodyweight completes without inventing zero load/body mass');
select ok((select actual_weight_kg is null and status='completed' from public.workout_sets where id=md5('bw')::uuid),'null external load preserved for bodyweight');
select set_config('body_test.removed',public.edit_workout(current_setting('body_test.session')::uuid,'add',(select id from public.exercises where slug='chin_up'))::text,true);
select public.edit_workout(current_setting('body_test.session')::uuid,'remove',null,current_setting('body_test.removed')::uuid);
select throws_ok($$select * from public.log_workout_set(current_setting('body_test.removed')::uuid,md5('removedset')::uuid,'add',null,md5('removedmutation')::uuid)$$,'23514',null,'removed exercise rejects new sets');
select lives_ok($$select public.end_workout(current_setting('body_test.session')::uuid,'completed')$$,'intentional finish keeps pending sets');
select is((select completion_status from public.workout_sessions where id=current_setting('body_test.session')::uuid),'partial','mixed completed/pending workout remains partial');
select is((select status from public.workout_sets where id=md5('set1')::uuid),'pending','finish never completes pending set');
select throws_ok($$select * from public.log_workout_set(current_setting('body_test.item')::uuid,md5('set1')::uuid,'save',3,md5('closed')::uuid,10,100)$$,'23514',null,'ordinary closed session RPC edits denied');
select throws_ok($$update public.workout_sets set actual_reps=99 where id=md5('bw')::uuid$$,'23514',null,'direct closed history UPDATE denied');
select throws_ok($$delete from public.workout_sets where id=md5('bw')::uuid$$,'23514',null,'direct closed history DELETE denied');
select * from finish();
rollback;
